from typing import Annotated
from pydantic import Field
import agent_framework as af

@af.{{b1}}(approval_mode={{b2}})
def issue_refund(
    order_id: Annotated[str, Field(description="Order to refund.")],
    amount: Annotated[float, Field(description="Amount in EUR.")],
) -> str:
    """Issue a refund for an order."""
    return f"Refunded {amount} EUR for {order_id}."

def build_agent(client) -> af.Agent:
    return af.Agent(client=client, instructions="Handle refunds.", {{b3}}=[issue_refund])
